func evGet(c *port.Cells, stride int32, row int32, f int32) int32 {
	return port.CellsAt(c, (row*stride)+f)
}

func evSet(c *port.Cells, stride int32, row int32, f int32, v int32) int32 {
	port.CellsSet(c, (row*stride)+f, v)
	return 0
}

func evCount(c *port.Cells, stride int32) int32 {
	return port.CellsLen(c) / stride
}

func evPush(c *port.Cells, stride int32) int32 {
	// Append a row of zeros and answer its index.
	var row int32 = port.CellsLen(c) / stride
	var i int32 = 0
	for i < stride {
		port.CellsPush(c, 0)
		i += 1
	}
	return row
}

func EvsInit(epages *port.Cells, views *port.Cells, pts *port.Cells, refs *port.Cells, etext *port.Cells, feats *port.Cells) int32 {
	// Empty the shared bundle.
	port.CellsDrop(epages, 0)
	port.CellsDrop(views, 0)
	port.CellsDrop(pts, 0)
	port.CellsDrop(refs, 0)
	port.CellsDrop(etext, 0)
	port.CellsDrop(feats, 0)
	return 0
}

